import os
import secrets

from flask import Flask, g, render_template

from . import auth, blog, db, security
from .config import Config

ERROR_MESSAGES = {
    400: ("Bad request", "The request could not be processed."),
    403: ("Forbidden", "You do not have permission to do that."),
    404: ("Not found", "The page you requested does not exist."),
    405: ("Method not allowed", "That action is not supported for this page."),
    413: ("Request too large", "The submitted data is too large."),
    500: ("Server error", "Something went wrong on our side."),
}


def create_app(test_config=None):
    app = Flask(__name__, instance_relative_config=True)
    app.config.from_object(Config)
    if test_config:
        app.config.update(test_config)

    if not app.config.get("DATABASE"):
        os.makedirs(app.instance_path, exist_ok=True)
        app.config["DATABASE"] = os.path.join(app.instance_path, "blog.db")

    if not app.config.get("SECRET_KEY"):
        if app.debug or app.config.get("TESTING"):
            app.config["SECRET_KEY"] = secrets.token_hex(32)
        else:
            raise RuntimeError(
                "SECRET_KEY environment variable must be set (or run with FLASK_DEBUG=1 for development)."
            )

    db.init_app(app)
    security.init_app(app)
    app.register_blueprint(auth.bp)
    app.register_blueprint(blog.bp)
    app.add_template_filter(format_timestamp, "datefmt")

    for code in ERROR_MESSAGES:
        app.register_error_handler(code, _render_error)

    with app.app_context():
        db.init_db()

    return app


def format_timestamp(value):
    """'2026-10-29T12:34:56.000000Z' -> '2026-10-29 12:34 UTC'."""
    return f"{value[:10]} {value[11:16]} UTC"


def _render_error(error):
    code = getattr(error, "code", 500) or 500
    title, message = ERROR_MESSAGES.get(code, ERROR_MESSAGES[500])
    if not hasattr(g, "user"):
        g.user = None
    return render_template("errors/error.html", code=code, title=title, message=message), code
